package alternate;public class Elimination{public record Result(java.util.List<Integer>removed,int survivor){}private static Result run(java.util.List<Integer>people){var removed=new java.util.ArrayList<Integer>();int next=0;while(people.size()>1){next=(next+1)%people.size();removed.add(people.remove(next));}return new Result(removed,people.get(0));}private static java.util.List<Integer>populate(java.util.List<Integer>list,int n){for(int i=1;i<=n;i++)list.add(i);return list;}public static Result array(int n){return run(populate(new java.util.ArrayList<>(),n));}public static Result linked(int n){return run(populate(new java.util.LinkedList<>(),n));}public static void main(String[]args){for(int warm=0;warm<20;warm++){array(500);linked(500);}for(int n:new int[]{500,1000}){long start=System.nanoTime();for(int r=0;r<30;r++)array(n);long a=System.nanoTime()-start;start=System.nanoTime();for(int r=0;r<30;r++)linked(n);long b=System.nanoTime()-start;System.out.println("N="+n+" ArrayList ns="+a+" LinkedList ns="+b+"; construction included; output excluded");}}}
